if (
  !["localhost", "127.0.0.1"].includes(
    new URL(process.env.DATABASE_URL!).hostname,
  )
)
  throw new Error("Browser tests require a local database.");
const pool = new Pool({ connectionString: process.env.DATABASE_URL });
async function tokenColor(target: Locator, name: string, property = "color") {
  return target.evaluate(
    (element, { name, property }) => {
      if (!getComputedStyle(element).getPropertyValue(name).trim())
        throw new Error(`Missing semantic token: ${name}`);
      const probe = document.createElement("span");
      probe.style.setProperty(property, `var(${name})`);
      element.append(probe);
      const value = getComputedStyle(probe).getPropertyValue(property);
      probe.remove();
      return value;
    },
    { name, property },
  );
}

async function selectTheme(page: Page, theme: "light" | "dark") {
  const palette = await page.locator("html").getAttribute("data-appearance");
  const trigger = page.getByRole("button", { name: "Choose appearance" });
  if ((await trigger.getAttribute("aria-disabled")) === "true") {
    // Model a preference change from another tab while the in-page picker is
    // locked. Keep the observed batch and its completion animation mounted.
    await page.evaluate((mode) => {
      localStorage.setItem("mailloop-theme", mode);
      window.dispatchEvent(
        new StorageEvent("storage", {
          key: "mailloop-theme",
          newValue: mode,
          storageArea: localStorage,
        }),
      );
    }, theme);
    await expect(page.locator("html")).toHaveAttribute("data-theme", theme);
    return;
  }
  await trigger.click();
  await page
    .getByRole("menuitemradio", {
      name: `${palette === "vercel" ? (theme === "dark" ? "Obsidian" : "Chalk") : theme === "dark" ? "Nightbloom" : "Lavender"} ${theme === "light" ? "Light" : "Dark"}`,
      exact: true,
    })
    .click();
}

async function grantPremiumPlan(userId: string) {
  await pool.query(
    `UPDATE "User" SET "planOverride"='PAID',"planOverrideStartsAt"=NOW(),"planOverrideReason"='Premium theme fixture' WHERE id=$1`,
    [userId],
  );
}

async function expectCenterToFit(card: Locator) {
  const center = card.locator(".batch-ring-center");
  const overflowing = await center.evaluate((element) => {
    const box = element.getBoundingClientRect();
    return [...element.children].flatMap((child) => {
      const range = document.createRange();
      range.selectNodeContents(child);
      return [...range.getClientRects()]
        .filter(
          (rect) => rect.left < box.left - 0.5 || rect.right > box.right + 0.5,
        )
        .map((rect) => ({
          text: child.textContent,
          left: rect.left,
          right: rect.right,
          centerLeft: box.left,
          centerRight: box.right,
        }));
    });
  });
  expect(overflowing).toEqual([]);
}
const test = base.extend<{ userId: string }>({
