test("delete history confirmation, cancellation, and completed-only deletion", async ({
  page,
  userId,
}) => {
  const templateId = randomUUID(),
    contactId = randomUUID(),
    campaignId = randomUUID();
  await pool.query(
    'INSERT INTO "Template" (id,"userId",name,subject,body) VALUES ($1,$2,$3,$4,$5)',
    [templateId, userId, "History template", "Hello", "Private body"],
  );
  await pool.query(
    'INSERT INTO "Contact" (id,"userId",name,email) VALUES ($1,$2,$3,$4)',
    [contactId, userId, "Completed recipient", "[REDACTED_EMAIL]"],
  );
  await pool.query(
    'INSERT INTO "Campaign" (id,"userId","templateId",status) VALUES ($1,$2,$3,$4)',
    [campaignId, userId, templateId, "SENDING"],
  );
  await pool.query(
    'INSERT INTO "Send" (id,"campaignId","contactId",status,"deliveryState",body,"recipientName","recipientEmail","sentAt") VALUES ($1,$2,$3,\'SENT\',\'DONE\',$4,$5,$6,now()), ($7,$2,$3,\'QUEUED\',\'READY\',$4,$8,$6,NULL)',
    [
      randomUUID(),
      campaignId,
      contactId,
      "Private body",
      "Completed recipient",
      "[REDACTED_EMAIL]",
      randomUUID(),
      "Pending recipient",
    ],
  );
  await page.goto("/settings");
  const trigger = page.getByRole("button", {
    name: "Delete history",
    exact: true,
  });
  const dialog = page.getByRole("dialog", {
    name: "Delete completed history?",
  });
  await trigger.click();
  await expect(dialog).toContainText("This can’t be undone.");
  await expect(
    dialog.getByRole("button", { name: "Cancel", exact: true }),
  ).toBeFocused();
  await page.keyboard.press("Escape");
  await expect(dialog).not.toBeVisible();
  await expect(trigger).toBeFocused();
  await trigger.click();
  const confirmation = dialog.getByLabel("Type Delete history to confirm");
  const deleteButton = dialog.getByRole("button", {
    name: "Delete history",
    exact: true,
  });
  await expect(deleteButton).toBeDisabled();
  await confirmation.fill("delete");
  await expect(deleteButton).toBeDisabled();
  await confirmation.fill("Delete history");
  await expect(deleteButton).toBeEnabled();
  await dialog.getByRole("button", { name: "Cancel", exact: true }).click();
  expect(
    (
      await pool.query(
        'SELECT body FROM "Send" WHERE "campaignId"=$1 AND status=\'SENT\'',
        [campaignId],
      )
    ).rows[0].body,
  ).toBe("Private body");
  await trigger.click();
  await expect(confirmation).toHaveValue("");
  await expect(deleteButton).toBeDisabled();
  await confirmation.fill("Delete history");
  await dialog
    .getByRole("button", { name: "Delete history", exact: true })
    .click();
  await expect(dialog).not.toBeVisible();
  await expect(trigger).toBeFocused();
  await expect(
    page
      .getByTestId("success-toast")
      .getByText("Completed history deleted.", { exact: true }),
  ).toBeVisible();
  expect(
    (
      await pool.query(
        `SELECT count(*)::int AS count FROM "Send" s JOIN "Campaign" c ON c.id=s."campaignId" WHERE c."userId"=$1 AND s.status IN ('SENT','REPLIED') AND s."historyDeletedAt" IS NULL`,
        [userId],
      )
    ).rows[0].count,
  ).toBe(0);
  expect(
    (
      await pool.query(
        'SELECT count(*)::int AS count FROM "DeliveryReceipt" WHERE "userId"=$1',
        [userId],
      )
    ).rows[0].count,
  ).toBe(1);
  await page.goto("/history");
  await expect(
    page.getByText("Completed recipient", { exact: true }),
  ).toHaveCount(0);
  await expect(
    page.getByText("Pending recipient", { exact: true }),
  ).toBeVisible();
});

test("delete history pending and failure feedback", async ({
  page,
  userId,
}) => {
  expect(userId).toBeTruthy();
  await page.goto("/settings");
  let release!: () => void;
  const gate = new Promise<void>((resolve) => {
    release = resolve;
  });
  await page.route("**/settings", async (route) => {
    if (
      route.request().method() !== "POST" ||
      !route.request().headers()["next-action"]
    )
      return route.continue();
    await gate;
    await route.fulfill({
      contentType: "text/x-component",
      body: '0:{"a":"$@1","f":"","b":""}\n1:{"ok":false,"message":"Could not delete history. Please try again."}\n',
    });
  });
  await page
    .getByRole("button", { name: "Delete history", exact: true })
    .click();
  const dialog = page.getByRole("dialog", {
    name: "Delete completed history?",
  });
  await dialog
    .getByLabel("Type Delete history to confirm")
    .fill("Delete history");
  await dialog
    .getByRole("button", { name: "Delete history", exact: true })
    .click();
  try {
    await expect(
      dialog.getByRole("button", { name: "Deleting…", exact: true }),
    ).toBeDisabled();
    await expect(
      dialog.getByRole("button", { name: "Cancel", exact: true }),
    ).toBeDisabled();
    await expect(
      dialog.getByLabel("Type Delete history to confirm"),
    ).toBeDisabled();
    await page.keyboard.press("Escape");
    await expect(dialog).toBeVisible();
  } finally {
    release();
  }
  await expect(dialog.getByRole("alert")).toContainText(
    "Could not delete history.",
  );
  await expect(
    dialog.getByRole("button", { name: "Delete history", exact: true }),
  ).toBeEnabled();
  await dialog.getByRole("button", { name: "Cancel", exact: true }).click();
  await expect(dialog).not.toBeVisible();
});

test("shortlist search visibility, fields, pagination, and clearing", async ({
  page,
  userId,
}) => {
  const addContact = async (index: number) => {
    await pool.query(
      'INSERT INTO "Contact" (id,"userId",name,email,company) VALUES ($1,$2,$3,$4,$5)',
      [
        randomUUID(),
        userId,
        `Person ${String(index).padStart(2, "0")}`,
        `person${index}@example.test`,
        "Searchable Company",
      ],
    );
  };
  for (let i = 0; i < 5; i++) await addContact(i);
  await page.goto("/compose");
  await expect(page.getByLabel("Search recipients")).toHaveCount(0);
  await addContact(5);
  await page.reload();
  const shortlist = page.getByRole("region", {
    name: "Your shortlist",
    exact: true,
  });
  const input = shortlist.getByLabel("Search recipients");
  await expect(input).toBeVisible();
  for (let i = 6; i < 25; i++) await addContact(i);
  await page.reload();
  await page.getByRole("checkbox", { name: /Person 00/ }).check();
  const search = async (query: string) => {
    await input.fill(query);
    await input.press("Enter");
    await expect(input).toHaveValue(query);
    await expect
      .poll(() => new URL(page.url()).searchParams.get("q"))
      .toBe(query);
  };
  // This recipient is outside the initial 20-row page.
  await search("pErSoN 24");
  await expect(shortlist.getByRole("checkbox")).toHaveCount(1);
  await expect(
    shortlist.getByRole("checkbox", { name: /Person 24/ }),
  ).toBeVisible();
  await expect(page.getByText("1 / 10 selected")).toBeVisible();
  await expect(
    page.getByText(
      "Your selection includes contacts from other search results.",
    ),
  ).toBeVisible();
  await search("[REDACTED_EMAIL]");
  await expect(
    shortlist.getByRole("checkbox", { name: /Person 17/ }),
  ).toBeVisible();
  await expect(shortlist.getByRole("checkbox")).toHaveCount(1);
  await search("searchable company");
  await expect(shortlist.getByRole("checkbox")).toHaveCount(20);
  await page.getByRole("link", { name: "Next", exact: true }).click();
  await expect(page).toHaveURL(/q=searchable\+company&page=2/);
  await expect(shortlist.getByRole("checkbox")).toHaveCount(5);
  await search("Person 24");
  await expect(page).not.toHaveURL(/page=/);
  await search("Nobody matches");
  await expect(shortlist.getByRole("checkbox")).toHaveCount(0);
  await expect(input).toBeVisible();
  await expect(
    shortlist.getByText("No matching contacts.", { exact: false }),
  ).toBeVisible();
  await shortlist.getByRole("link", { name: "Clear search" }).click();
  await expect(page).toHaveURL(/\/compose$/);
  await expect(input).toHaveValue("");
  await expect(
    shortlist.getByRole("checkbox", { name: /Person 00/ }),
  ).toBeChecked();
  // Active searches remain available even for a small shortlist or zero matches.
  await pool.query('DELETE FROM "Contact" WHERE "userId"=$1 AND name != $2', [
    userId,
    "Person 00",
  ]);
  await page.goto("/compose?q=Nobody");
  await expect(input).toBeVisible();
  await shortlist.getByRole("link", { name: "Clear search" }).click();
  await expect(page.getByLabel("Search recipients")).toHaveCount(0);
});

test("search results highlight briefly and restart on repeated searches", async ({
  page,
  userId,
}) => {
  await pool.query(
    'INSERT INTO "Contact" (id,"userId",name,email) VALUES ($1,$2,$3,$4)',
    [randomUUID(), userId, "Ada Highlight", "[REDACTED_EMAIL]"],
  );
  for (let i = 0; i < 5; i++)
    await pool.query(
      'INSERT INTO "Contact" (id,"userId",name,email) VALUES ($1,$2,$3,$4)',
      [
        randomUUID(),
        userId,
        `Other Highlight ${i}`,
        `other-highlight${i}@example.test`,
      ],
    );
  await grantPremiumPlan(userId);
  await page.goto("/compose");
  const highlight = page.locator('.recipient-card > [aria-hidden="true"]');
  await expect(highlight).toHaveCount(0);
  await page.getByLabel("Search recipients").fill("Ada");
  for (const motion of ["no-preference", "reduce"] as const) {
    await page.emulateMedia({ reducedMotion: motion });
    await page.getByRole("button", { name: "Search", exact: true }).click();
    await expect(
      page.getByRole("checkbox", { name: /Ada Highlight/ }),
    ).toBeVisible();
    await expect(highlight).toHaveCSS("opacity", "1");
    await expect(highlight).toHaveCSS("pointer-events", "none");
    await page.getByRole("checkbox", { name: /Ada Highlight/ }).check();
    await expect(highlight).toHaveCSS("opacity", "0", { timeout: 5000 });
    await expect(
      page.getByRole("checkbox", { name: /Ada Highlight/ }),
    ).toBeChecked();
  }
  const colors = new Set<string>();
  for (const theme of [
    "Lavender Light",
    "Nightbloom Dark",
    "Chalk Light",
    "Obsidian Dark",
  ]) {
    await page.getByRole("button", { name: "Choose appearance" }).click();
    await page.getByRole("menuitemradio", { name: theme, exact: true }).click();
    await page.getByRole("button", { name: "Search", exact: true }).click();
    await expect(highlight).toHaveCSS("opacity", "1");
    const { color, themeColor } = await highlight.evaluate((element) => {
      const probe = document.createElement("span");
      probe.style.color = "var(--ring)";
      element.append(probe);
      const themeColor = getComputedStyle(probe).color;
      probe.remove();
      return { color: getComputedStyle(element).outlineColor, themeColor };
    });
    expect(color).toBe(themeColor);
    colors.add(color);
    await page.locator(".recipient-card").screenshot({
      path: test.info().outputPath(`search-highlight-${theme}.png`),
    });
    await expect(highlight).toHaveCSS("opacity", "0", { timeout: 5000 });
  }
  expect(colors.size).toBeGreaterThan(1);
  await page.getByRole("link", { name: "Clear search" }).click();
  await expect(highlight).toHaveCount(0);
});

test("button effects and recipient search pending feedback", async ({
  page,
  userId,
}) => {
  await pool.query(
    'INSERT INTO "Contact" (id,"userId",name,email) VALUES ($1,$2,$3,$4)',
    [randomUUID(), userId, "Ada Search", "[REDACTED_EMAIL]"],
  );
  for (let i = 0; i < 10; i++)
    await pool.query(
      'INSERT INTO "Contact" (id,"userId",name,email) VALUES ($1,$2,$3,$4)',
      [randomUUID(), userId, `Other ${i}`, `other${i}@example.test`],
    );
  await page.emulateMedia({ reducedMotion: "no-preference" });
  await page.goto("/compose");
  const search = page.getByRole("button", { name: "Search", exact: true });
  if (test.info().project.name === "desktop") {
    for (const control of [
      search,
      page.getByRole("button", { name: "Account menu" }),
    ]) {
      await control.hover();
      await expect(control).toHaveCSS("translate", "0px -2px");
      await page.mouse.down();
      await expect(control).toHaveCSS("translate", "0px");
      await page.mouse.up();
    }
    await page.mouse.click(0, 0);
  }
  const width = (await search.boundingBox())!.width;
  let release!: () => void;
  const gate = new Promise<void>((resolve) => {
    release = resolve;
  });
  await page.route("**/compose?**", async (route) => {
    if (new URL(route.request().url()).searchParams.get("q") === "Ada")
      await gate;
    await route.continue();
  });
  try {
    await page.getByLabel("Search recipients").fill("Ada");
    await search.click();
    const searching = page.getByRole("button", {
      name: "Searching…",
      exact: true,
    });
    await expect(searching).toBeDisabled();
    await expect(searching).toHaveAttribute("aria-busy", "true");
    await expect(searching.locator("svg")).toHaveCSS(
      "animation-name",
      "button-spin",
    );
    await expect(searching).toHaveCSS("translate", "none");
    expect((await searching.boundingBox())!.width).toBe(width);
  } finally {
    release();
  }
  await expect(page).toHaveURL(/q=Ada/);
  await expect(search).toBeEnabled();
  await expect(
    page.getByRole("checkbox", { name: /Ada Search/ }),
  ).toBeVisible();
  await page.getByLabel("Search recipients").fill("No matching recipient");
  await search.click();
  await expect(page.getByRole("checkbox", { name: /Ada Search/ })).toHaveCount(
    0,
  );
  await expect(search).toBeEnabled();
  await page.emulateMedia({ reducedMotion: "reduce" });
  await search.hover();
  await expect(search).toHaveCSS("translate", "none");
  await expect(search).toHaveCSS("transition-duration", "0s");
  for (const theme of ["light", "dark"] as const) {
    await selectTheme(page, theme);
    const form = page.locator(".recipient-panel .compose-search");
    await expect(form).toBeVisible();
    const fits = await form.evaluate((element) => {
      const box = element.getBoundingClientRect();
      return (
        [...element.children].every((child) => {
          const rect = child.getBoundingClientRect();
          return rect.left >= box.left && rect.right <= box.right + 1;
        }) && box.right <= window.innerWidth
      );
    });
    expect(fits).toBe(true);
    await form.screenshot({
      path: test.info().outputPath(`recipient-search-${theme}.png`),
    });
  }
});

test("manual reply controls and Settings reconnection without banners", async ({
  page,
  userId,
}) => {
  await pool.query(
    'UPDATE "User" SET "gmailScopes"=ARRAY[]::TEXT[], "gmailSendOnlyConsentAt"=NULL WHERE id=$1',
    [userId],
  );
  const contactId = randomUUID(),
    templateId = randomUUID(),
    campaignId = randomUUID(),
    sendId = randomUUID(),
    uncertainId = randomUUID();
  await pool.query(
    'INSERT INTO "Contact" (id,"userId",name,email,"jobRole") VALUES ($1,$2,$3,$4,$5)',
    [contactId, userId, "Manual Recipient", "[REDACTED_EMAIL]", "Engineer"],
  );
  await pool.query(
    'INSERT INTO "Template" (id,"userId",name,subject,body) VALUES ($1,$2,$3,$4,$5)',
    [templateId, userId, "Manual template", "Hello", "Hello"],
  );
  await pool.query(
    'INSERT INTO "Campaign" (id,"userId","templateId",status) VALUES ($1,$2,$3,$4)',
    [campaignId, userId, templateId, "COMPLETED_WITH_ERRORS"],
  );
  await pool.query(
    `INSERT INTO "Send" (id,"campaignId","contactId","recipientEmail","recipientName",status,"deliveryState","sentAt","attemptedAt") VALUES ($1,$2,$3,'[REDACTED_EMAIL]','Manual Recipient','SENT','DONE',NOW(),NOW()),($4,$2,$3,'[REDACTED_EMAIL]','Uncertain Recipient','FAILED','UNCERTAIN',NULL,NOW())`,
    [sendId, campaignId, contactId, uncertainId],
  );
  await pool.query(
    `UPDATE "Send" SET "recipientCompany"='Research team', "recipientRole"='Software Engineer Intern', "templateName"='Intro' WHERE "campaignId"=$1`,
    [campaignId],
  );
  await page.goto("/history");
  await expect(
    page.getByText(/Automatic reply detection has been replaced/),
  ).toHaveCount(0);
  await expect(
    page.getByRole("button", { name: "Check Replies", exact: true }),
  ).toHaveCount(0);
  const row = page.getByRole("row").filter({ hasText: "[REDACTED_EMAIL]" });
  await expect(row.getByRole("button")).toHaveCount(2);
  await expect(
    row.getByRole("button", { name: "In shortlist", exact: true }),
  ).toBeDisabled();
  const actionsHeader = page.getByRole("columnheader", {
    name: "Actions",
    exact: true,
    includeHidden: true,
  });
  if (test.info().project.name === "mobile")
    await expect(actionsHeader).toBeHidden();
  else await expect(actionsHeader).toBeVisible();
  await expect(
    page.getByRole("button", {
      name: /^(Mark bounced|Do not contact|Found in Sent|Cancel email|Cancel this email)$/,
    }),
  ).toHaveCount(0);
  expect(
    (await page.getByRole("region", { name: "Follow-ups due" }).boundingBox())!
      .height,
  ).toBeLessThan(140);
  if (test.info().project.name === "desktop") {
    expect((await row.boundingBox())!.height).toBeLessThan(180);
    const emailBox = await row
      .getByText("[REDACTED_EMAIL]", { exact: true })
      .boundingBox();
    expect(emailBox!.height).toBeLessThan(25);
  }
  await page.screenshot({
    path: test.info().outputPath("history-compact.png"),
    fullPage: true,
    caret: "initial",
  });
  await page.emulateMedia({ reducedMotion: "reduce" });
  await selectTheme(page, "dark");
  await expect(page.locator("html")).toHaveAttribute("data-theme", "dark");
  await page
    .getByRole("region", { name: "Delivery history table" })
    .screenshot({ path: test.info().outputPath("history-compact-dark.png") });
  await row.getByRole("button", { name: "Mark replied", exact: true }).click();
  await expect(row.getByRole("cell").nth(4)).toHaveText("Replied");
  await expect(
    row.getByText("Reply marked manually", { exact: true }),
  ).toHaveCount(0);
  const undo = row.getByRole("button", { name: "Undo reply", exact: true });
  await expect(undo).toBeVisible();
  await expect(row.getByRole("button")).toHaveCount(2);
  const actions = row.getByRole("cell").nth(5);
  const rightEdge = (await actions.boundingBox())!;
  const lastButton = (await row.getByRole("button").last().boundingBox())!;
  expect(lastButton.x + lastButton.width).toBeCloseTo(
    rightEdge.x + rightEdge.width,
    0,
  );
  await page
    .getByRole("region", { name: "Delivery history table" })
    .screenshot({ path: test.info().outputPath("history-replied-dark.png") });
  const uncertain = page
