        await page.evaluate(() => document.documentElement.scrollWidth),
      ).toBeLessThanOrEqual(width);
      expect(
        await available.evaluate((el) =>
          [...el.querySelectorAll("td")].every(
            (cell) => cell.scrollWidth <= cell.clientWidth + 1,
          ),
        ),
      ).toBe(true);
    }
    const add = available.getByRole("button", {
      name: "Add to shortlist",
      exact: true,
    });
    await add.focus();
    await expect(add).toBeFocused();
    await expect(add).toHaveCSS("outline-style", "solid");
    await expect(page.getByRole("tooltip")).toContainText("Add to shortlist");
    const bounds = (await page.getByRole("tooltip").boundingBox())!;
    expect(bounds.x).toBeGreaterThanOrEqual(0);
    expect(bounds.x + bounds.width).toBeLessThanOrEqual(
      page.viewportSize()!.width,
    );
    await page.keyboard.press("Escape");
    await expect(page.getByRole("tooltip")).toHaveCount(0);
    const unavailable = row("archived").getByRole("button", {
      name: /shortlist/,
