  const gate = new Promise<void>((resolve) => {
    release = resolve;
  });
  const delayAction = async (route: Route) => {
    if (
      route.request().method() === "POST" &&
      route.request().headers()["next-action"]
    )
      await gate;
    await route.continue();
  };
