    release();
  }
  await expect(
    row("replied").getByRole("button", { name: "In shortlist", exact: true }),
  ).toBeDisabled();
  await page.unroute("**/history", delayAction);
  await page.reload();
  await expect(
    row("replied").getByRole("button", { name: "In shortlist", exact: true }),
  ).toBeDisabled();
