  try {
    await context.addCookies(await page.context().cookies());
    const localPage = await context.newPage();
    const hydrationErrors: string[] = [];
    localPage.on("pageerror", (error) => hydrationErrors.push(error.message));
    localPage.on("console", (message) => {
      if (message.type() === "error" && /hydrat/i.test(message.text()))
        hydrationErrors.push(message.text());
    });
    await localPage.goto(page.url());
    const time = localPage
      .getByRole("region", { name: "Delivery history table" })
      .getByRole("row")
      .filter({ hasText: longEmail })
      .locator("time");
    await expect(time.locator("span").nth(0)).toHaveText("Sep 3, 2026");
    await expect(time.locator("span").nth(1)).toHaveText("11:45 AM");
    expect(hydrationErrors).toEqual([]);
  } finally {
    await context.close();
  }
});

