});

test("page skeletons stream while data loads and shimmer respects reduced motion", async ({
  page,
  userId,
}) => {
  const attachmentId = randomUUID();
  await pool.query(
    'INSERT INTO "Attachment" (id,"userId","fileName","storagePath") VALUES ($1,$2,$3,$4)',
    [attachmentId, userId, "resume.pdf", "test-skeleton.pdf"],
  );
  await pool.query(
    'UPDATE "User" SET "preferredRoles"=$2,"currentAttachmentId"=$3 WHERE id=$1',
    [userId, ["Engineer"], attachmentId],
  );
  await page.addInitScript(() =>
    localStorage.setItem("mailloop-theme", "dark"),
  );
  const blocker = await pool.connect();
  try {
    for (const [route, table] of [
      ["compose", "Contact"],
      ["templates", "Contact"],
      ["history", "Send"],
      ["contacts", "Contact"],
      ["settings", "Attachment"],
      ["billing", "Send"],
    ]) {
      await page.emulateMedia({ reducedMotion: "no-preference" });
      await blocker.query("BEGIN");
      await blocker.query(`LOCK TABLE "${table}" IN ACCESS EXCLUSIVE MODE`);
      try {
        await page.goto(`/${route}`, { waitUntil: "commit" });
        const loading = page.getByRole("status", {
          name: `Loading ${route}`,
          exact: true,
        });
        await expect(loading).toBeVisible();
        // Shared quota and role queries can block the header for any locked
        // table. A streamed shell still exposes its navigation placeholder.
        await expect(
          page
            .getByRole("navigation", { name: "Main navigation" })
            .or(page.locator(".workspace-nav-placeholder"))
            .first(),
        ).toBeVisible();
        const skeleton = loading.locator(".skeleton").first();
        await expect
          .poll(() =>
            skeleton.evaluate(
              (element) => getComputedStyle(element, "::after").animationName,
            ),
          )
          .toBe("skeleton-shimmer");
        await expect(page.locator("html")).toHaveAttribute(
          "data-theme",
          "dark",
        );
        expect(
          await page.evaluate(
            () => document.documentElement.scrollWidth <= innerWidth + 1,
          ),
        ).toBe(true);
        await page.emulateMedia({ reducedMotion: "reduce" });
        await expect
          .poll(() =>
            skeleton.evaluate(
              (element) => getComputedStyle(element, "::after").display,
            ),
          )
          .toBe("none");
        await page.screenshot({
          path: `/tmp/mailloop-skeleton-${route}-${test.info().project.name}.png`,
          fullPage: true,
        });
      } finally {
        await blocker.query("ROLLBACK");
      }
      await expect(
        page.locator('[role="status"][aria-busy="true"]'),
      ).toHaveCount(0);
      await expect(page.locator("main h1")).toBeVisible();
      await expect(
        page.getByRole("navigation", { name: "Main navigation" }),
      ).toBeVisible();
    }
  } finally {
    await blocker.query("ROLLBACK");
    blocker.release();
  }
});

