test("delayed queued delivery warning and cancellation unlock sending", async ({
  page,
  userId,
}) => {
  const templateId = randomUUID(),
    contactId = randomUUID(),
    campaignId = randomUUID();
  await pool.query(
    `INSERT INTO "Template" (id,"userId",name,subject,body) VALUES ($1,$2,'Queue test','Hello','Hello')`,
    [templateId, userId],
  );
  await pool.query(
    `INSERT INTO "Contact" (id,"userId",name,email) VALUES ($1,$2,'Alex','[REDACTED_EMAIL]')`,
    [contactId, userId],
  );
  await pool.query(
    `INSERT INTO "Campaign" (id,"userId","templateId",status) VALUES ($1,$2,$3,'SENDING')`,
    [campaignId, userId, templateId],
  );
  await pool.query(
    `INSERT INTO "Send" (id,"campaignId","contactId",status,"deliveryState","recipientName","recipientEmail") VALUES ($1,$2,$3,'QUEUED','READY','Alex','[REDACTED_EMAIL]')`,
    [randomUUID(), campaignId, contactId],
  );
  for (let index = 1; index < 10; index++) {
    const otherContactId = randomUUID();
    await pool.query(
      `INSERT INTO "Contact" (id,"userId",name,email) VALUES ($1,$2,$3,$4)`,
      [otherContactId, userId, `Other ${index}`, `other${index}@example.test`],
    );
    await pool.query(
      `INSERT INTO "Send" (id,"campaignId","contactId","recipientEmail") VALUES ($1,$2,$3,$4)`,
      [randomUUID(), campaignId, otherContactId, `other${index}@example.test`],
    );
  }
  await page.goto("/history");
  await expect(
    page.getByText("Mailloop retries automatically", { exact: false }),
  ).toBeHidden();
  await expect(
    page.getByRole("button", { name: "Cancel this email", exact: true }),
  ).toHaveCount(0);
  await page.goto("/compose");
  await expect(page.getByRole("checkbox", { name: /Alex/ })).toBeDisabled();
  // An old batch with a recent active attempt must not warn for any recipient.
  await pool.query(
    `UPDATE "Send" SET "createdAt"=NOW()-INTERVAL '5 minutes' WHERE "campaignId"=$1`,
    [campaignId],
  );
  await pool.query(
    `UPDATE "Send" SET "deliveryState"='ATTEMPTING', "attemptedAt"=NOW()-INTERVAL '30 seconds' WHERE "campaignId"=$1 AND "recipientEmail"='[REDACTED_EMAIL]'`,
    [campaignId],
  );
  await page.goto("/history");
  await expect(page.getByText(/Taking longer than usual/)).toHaveCount(0);
  await pool.query(
    `UPDATE "Send" SET "attemptedAt"=NOW()-INTERVAL '150 seconds' WHERE "campaignId"=$1 AND "recipientEmail"='[REDACTED_EMAIL]'`,
    [campaignId],
  );
  await page.reload();
  await expect(
    page.getByText("[REDACTED_EMAIL] — Taking longer than usual.", {
      exact: true,
    }),
  ).toBeVisible();
  await expect(page.getByText(/Taking longer than usual/)).toHaveCount(1);
  await expect(
    page.getByRole("button", { name: "Cancel this email", exact: true }),
  ).toHaveCount(0);
  await pool.query(
    `UPDATE "Send" SET "deliveryState"='READY', "attemptedAt"=NULL, "createdAt"=NOW()-INTERVAL '6 minutes' WHERE "campaignId"=$1 AND "recipientEmail"='[REDACTED_EMAIL]'`,
    [campaignId],
  );
  await pool.query(
    `UPDATE "Send" SET "createdAt"=NOW() - INTERVAL '5 minutes' WHERE "campaignId"=$1 AND "recipientEmail" != '[REDACTED_EMAIL]'`,
    [campaignId],
  );
  await page.goto("/history");
  await expect(
    page.getByText("Mailloop retries automatically", { exact: false }),
  ).toBeVisible();
  expect(
    await page.evaluate(() => document.documentElement.scrollWidth),
  ).toBeLessThanOrEqual(page.viewportSize()!.width);
  await page.screenshot({
    path: `/tmp/mailloop-queue-warning-${test.info().project.name}.png`,
    fullPage: true,
  });
  await page
    .getByRole("button", { name: "Cancel this email", exact: true })
    .click();
  await expect(
    page.getByText("1 queued email cancelled.", { exact: true }),
  ).toBeVisible();
  await expect(
    page.getByRole("button", { name: "Cancel this email", exact: true }),
  ).toHaveCount(0);
  const cancelled = await pool.query(
    `SELECT s.status,s."deliveryState" FROM "Send" s JOIN "Campaign" c ON c.id=s."campaignId" WHERE c."userId"=$1`,
    [userId],
  );
  expect(cancelled.rows.filter((row) => row.status === "CANCELLED")).toEqual([
    { status: "CANCELLED", deliveryState: "DONE" },
  ]);
  expect(cancelled.rows.filter((row) => row.status === "QUEUED")).toHaveLength(
    9,
  );
  await expect(page.getByText(/Taking longer than usual/)).toHaveCount(0);
  await page.reload();
  await expect(page.getByText(/Taking longer than usual/)).toHaveCount(0);
  await page.goto("/compose");
  await expect(page.getByRole("checkbox", { name: /Alex/ })).toBeEnabled();
});
