test("duplicate warnings use the exact emailed address and allow an intentional resend", async ({
  page,
  userId,
}) => {
  const templateId = randomUUID();
  const campaignId = randomUUID();
  const editedId = randomUUID();
  const replacementId = randomUUID();
  const latest = "2026-10-10T10:00:00.000Z";
  await pool.query(
    'INSERT INTO "Template" (id,"userId",name,subject,body) VALUES ($1,$2,$3,$4,$5)',
    [templateId, userId, "Email warning", "Hi {{name}}", "Hello {{role}}"],
  );
  for (const [id, email, followUp] of [
    [editedId, "[REDACTED_EMAIL]", null],
    [randomUUID(), "[REDACTED_EMAIL]", null],
    [replacementId, "[REDACTED_EMAIL]", new Date()],
  ]) {
    await pool.query(
      'INSERT INTO "Contact" (id,"userId",name,email,"jobRole","followUpRequestedAt") VALUES ($1,$2,$3,$4,$5,$6)',
      [id, userId, "Alex", email, "Engineer", followUp],
    );
  }
  await pool.query(
    'INSERT INTO "Campaign" (id,"userId","templateId",status) VALUES ($1,$2,$3,$4)',
    [campaignId, userId, templateId, "COMPLETED"],
  );
  for (const [status, sentAt] of [
    ["SENT", "2026-10-09T10:00:00.000Z"],
    ["REPLIED", latest],
  ]) {
    await pool.query(
      'INSERT INTO "Send" (id,"campaignId","contactId",status,"deliveryState","recipientEmail","sentAt","createdAt","recipientName") VALUES ($1,$2,$3,$4,$5,$6,$7,$7,$8)',
      [
        randomUUID(),
        campaignId,
        editedId,
        status,
        "DONE",
        "[REDACTED_EMAIL]",
        sentAt,
        "Alex",
      ],
    );
  }
  await page.goto("/compose");
  const prior = page
    .locator(".recipient-card")
    .filter({ hasText: "[REDACTED_EMAIL]" });
  const changed = page
    .locator(".recipient-card")
    .filter({ hasText: "[REDACTED_EMAIL]" });
  const sameName = page
    .locator(".recipient-card")
    .filter({ hasText: "[REDACTED_EMAIL]" });
  await expect(page.locator(".recipient-card")).toHaveCount(3);
  await expect(page.locator(".recipient-card-emailed")).toHaveCount(1);
  await expect(prior.locator(".recipient-warning")).toContainText(
    "You already emailed this address on",
  );
  await expect(prior.locator(".recipient-warning time")).toHaveAttribute(
    "datetime",
    latest,
  );
  await expect(changed.locator(".recipient-warning")).toHaveCount(0);
  await expect(sameName.locator(".recipient-warning")).toHaveCount(0);
  for (const theme of ["light", "dark"]) {
    await page.evaluate(
      (theme) => localStorage.setItem("mailloop-theme", theme),
      theme,
    );
    await page.reload();
    const warningBackground = () =>
      prior.evaluate((el) => {
        const probe = document.createElement("span");
        probe.style.background = "var(--recipients-pill-bg)";
        el.append(probe);
        const value = getComputedStyle(probe).backgroundColor;
        probe.remove();
        return value;
      });
    await expect.poll(warningBackground).not.toBe("rgba(0, 0, 0, 0)");
    const background = await warningBackground();
    await expect(prior).toHaveCSS("background-color", background);
    expect(
      await changed.evaluate(
        (element) => getComputedStyle(element).backgroundColor,
      ),
    ).not.toBe(background);
    expect(
      await sameName.evaluate(
        (element) => getComputedStyle(element).backgroundColor,
      ),
    ).not.toBe(background);
  }
  await page
    .getByLabel("Choose a template", { exact: true })
    .selectOption(templateId);
  await changed.getByRole("checkbox").check();
  await expect(page.locator(".compose-send-button")).toBeEnabled();
  await changed.getByRole("checkbox").uncheck();
  await prior.getByRole("checkbox").check();
  await expect(page.locator(".compose-send-button")).toBeEnabled();
  await expect(
    page.getByText("Allow intentional follow-ups", { exact: true }),
  ).toHaveCount(0);
  await prior.getByRole("checkbox").uncheck();
  await expect(page.locator(".compose-send-button")).toBeDisabled();
  await prior.getByRole("checkbox").check();
  await page
    .getByRole("button", { name: "Send to 1 recipient", exact: true })
    .click();
  // Queue persistence verifies the resend even when local Inngest is unavailable.
  await expect
    .poll(async () => {
      const sends = await pool.query(
        'SELECT s."recipientEmail" FROM "Send" s JOIN "Campaign" c ON c.id=s."campaignId" WHERE c."userId"=$1 AND s.status=\'QUEUED\'',
        [userId],
      );
      return sends.rows;
    })
    .toEqual([{ recipientEmail: "[REDACTED_EMAIL]" }]);
});

