base(
  "theme: system default, reveal, rapid clicks, storage events and reduced motion",
  async ({ page }) => {
    await page.emulateMedia({
      colorScheme: "dark",
      reducedMotion: "no-preference",
    });
    await page.addInitScript(() => {
      const seen: string[] = [];
      Object.assign(window, { initialThemes: seen });
      new MutationObserver(() => {
        const theme = document.documentElement?.dataset.theme;
        if (theme) seen.push(theme);
      }).observe(document, {
        attributes: true,
        attributeFilter: ["data-theme"],
        subtree: true,
      });
    });
    await page.goto("/");
    await expect(page.locator("html")).toHaveAttribute("data-theme", "dark");
    expect(
      await page.evaluate(
        () =>
          (window as typeof window & { initialThemes: string[] })
            .initialThemes[0],
      ),
    ).toBe("dark");
    await page
      .getByRole("banner")
      .getByRole("button", { name: "Switch to light theme", exact: true })
      .click();
    await expect(page.locator("html")).toHaveAttribute("data-theme", "light");
    if (
      await page.evaluate(
        () => typeof document.startViewTransition === "function",
      )
    ) {
      await expect
        .poll(() =>
          page.evaluate(() =>
            document
              .getAnimations()
              .some((animation) =>
                (animation.effect as KeyframeEffect)
                  .getKeyframes()
                  .some(
                    (frame) =>
                      typeof frame.clipPath === "string" &&
                      frame.clipPath.startsWith("circle("),
                  ),
              ),
          ),
        )
        .toBe(true);
    }
    for (const theme of ["dark", "light", "dark"] as const) {
      await page
        .getByRole("button", { name: `Switch to ${theme} theme` })
        .click();
      await expect(page.locator("html")).toHaveAttribute("data-theme", theme);
    }
    await expect(page.locator("html")).toHaveAttribute("data-theme", "dark");
    await page.reload();
    await expect(page.locator("html")).toHaveAttribute("data-theme", "dark");
    await page.evaluate(() => {
      localStorage.setItem("mailloop-theme", "light");
      window.dispatchEvent(
        new StorageEvent("storage", {
          key: "mailloop-theme",
          newValue: "light",
        }),
      );
    });
    await expect(page.locator("html")).toHaveAttribute("data-theme", "light");
    await page.emulateMedia({ reducedMotion: "reduce" });
    await page
      .getByRole("banner")
      .getByRole("button", { name: "Switch to dark theme", exact: true })
      .click();
    await expect(page.locator("html")).toHaveAttribute("data-theme", "dark");
    await expect(page.locator("html")).not.toHaveAttribute("data-theme-reveal");
    expect(
      await page.evaluate(() =>
        document
          .getAnimations()
          .some((animation) =>
            (animation.effect as KeyframeEffect)
              .getKeyframes()
              .some(
                (frame) =>
                  typeof frame.clipPath === "string" &&
                  frame.clipPath.startsWith("circle("),
              ),
          ),
      ),
    ).toBe(false);
  },
);

