for (const clearingMethod of [
  "Ctrl+Backspace",
  "repeated Backspace",
  "select-all/delete",
]) {
  test(`contact suggested name can be cleared with ${clearingMethod}`, async ({
    page,
    userId,
  }) => {
    await pool.query('UPDATE "User" SET "preferredRoles"=$2 WHERE id=$1', [
      userId,
      ["Engineer"],
    ]);
    await page.goto("/contacts");
    const form = page.locator(".contact-form");
    const email = form.getByLabel("Email", { exact: true });
    const name = form.getByLabel("Name", { exact: true });
    await email.fill("[REDACTED_EMAIL]");
    await expect(name).toHaveValue("Test");
    await email.fill("[REDACTED_EMAIL]");
    await expect(name).toHaveValue("Sam");
    await email.fill("[REDACTED_EMAIL]");
    await expect(name).toHaveValue("Test");
    await name.focus();
    await name.press("End");
    if (clearingMethod === "Ctrl+Backspace") {
      await name.press("Control+Backspace");
    } else if (clearingMethod === "repeated Backspace") {
      for (const remaining of ["Tes", "Te", "T", ""]) {
        await name.press("Backspace");
        await expect(name).toHaveValue(remaining);
      }
    } else {
      await name.press("ControlOrMeta+a");
      await name.press("Delete");
    }
    await expect(name).toHaveValue("");
    await email.fill("[REDACTED_EMAIL]");
    await expect(name).toHaveValue("");
    await name.fill("  Taylor  ");
    await expect(name).toHaveValue("  Taylor  ");
    await form.getByLabel("Job role", { exact: true }).fill("Engineer");
    await form
      .getByRole("button", { name: "Save contact", exact: true })
      .click();
    await expect(page.getByTestId("success-toast")).toContainText(
      "Contact saved successfully.",
    );
    const saved = await pool.query(
      'SELECT name,email FROM "Contact" WHERE "userId"=$1',
      [userId],
    );
    expect(saved.rows).toEqual([
      { name: "Taylor", email: "[REDACTED_EMAIL]" },
    ]);
    await expect(email).toHaveValue("");
    await expect(name).toHaveValue("");
    await email.fill("[REDACTED_EMAIL]");
    await expect(name).toHaveValue("Fresh");
    await email.fill("[REDACTED_EMAIL]");
    await expect(name).toHaveValue("Another");
  });
}

