test("contact email lookup ignores stale results, clearing, resets, and failures", async ({
  page,
  userId,
}) => {
  expect(userId).toBeTruthy();
  await page.goto("/contacts");
  const form = page.locator(".contact-form"),
    email = form.getByLabel("Email", { exact: true }),
    note = form.locator("#contact-email-history-note");
  let release!: () => void;
  let started!: () => void;
  const requested = new Promise<void>((resolve) => {
    started = resolve;
  });
  const gate = new Promise<void>((resolve) => {
    release = resolve;
  });
  await page.route("**/contacts", async (route) => {
    if (!route.request().headers()["next-action"]) return route.continue();
    if (route.request().postData()?.includes("[REDACTED_EMAIL]")) {
      started();
      await gate;
      return route.fulfill({
        contentType: "text/x-component",
        body: '0:{"a":"$@1","f":"","b":""}\n1:true\n',
      });
    }
    return route.fulfill({
      contentType: "text/x-component",
      body: '0:{"a":"$@1","f":"","b":""}\n1:false\n',
    });
  });
  await email.fill("[REDACTED_EMAIL]");
  await requested;
  await email.fill("[REDACTED_EMAIL]");
  release();
  await expect(note).toBeEmpty();
  await page.waitForTimeout(700);
  await expect(note).toBeEmpty();
  await email.fill("");
  await expect(note).toBeEmpty();
  await email.fill("[REDACTED_EMAIL]");
  await expect(note).not.toBeEmpty();
  await form.evaluate((el) => (el as HTMLFormElement).reset());
  await expect(email).toHaveValue("");
  await expect(note).toBeEmpty();
  await page.unroute("**/contacts");
  await page.route("**/contacts", (route) =>
    route.request().headers()["next-action"] ? route.abort() : route.continue(),
  );
  await email.fill("[REDACTED_EMAIL]");
  await page.waitForTimeout(700);
  await expect(note).toBeEmpty();
  await expect(
    form.getByRole("button", { name: "Save contact", exact: true }),
  ).toBeEnabled();
});

