test("quota refreshes while idle and on return, retains failed counts, and avoids overlapping lookups", async ({
  page,
  userId,
}) => {
  await seedReadinessWorkspace(userId);
  await page.clock.install();
  let requests = 0;
  let fail = false;
  let used = 55;
  let held: Route | undefined;
  let hold = false;
  await page.route("**/api/quota", async (route) => {
    requests++;
    if (hold) {
      held = route;
      return;
    }
    await route.fulfill({
      status: fail ? 503 : 200,
      json: fail ? { error: "Unavailable" } : { used, limit: 200 },
    });
  });
  await page.goto("/usage");
  const quota = page.getByRole("img", { name: /used or queued of 200;/ });
  await expect(quota).toHaveAccessibleName(
    "56 used or queued of 200; 144 remaining",
  );
  // Hydrate the workspace before advancing the clock past the refresh interval.
  await page.getByRole("button", { name: "Account menu", exact: true }).click();
  await expect(page.getByRole("menu", { name: "Account" })).toBeVisible();
  await page.keyboard.press("Escape");
  await page.clock.runFor(60000);
  await expect(quota).toHaveAccessibleName(
    "55 used or queued of 200; 145 remaining",
  );
  fail = true;
  await page.clock.runFor(60000);
  await expect.poll(() => requests).toBe(2);
  await expect(quota).toHaveAccessibleName(
    "55 used or queued of 200; 145 remaining",
  );
  fail = false;
  used = 54;
  await page.evaluate(() => window.dispatchEvent(new Event("focus")));
  await expect(quota).toHaveAccessibleName(
    "54 used or queued of 200; 146 remaining",
  );
  await page.evaluate(() => {
    Object.defineProperty(document, "visibilityState", {
      configurable: true,
      value: "hidden",
    });
    document.dispatchEvent(new Event("visibilitychange"));
  });
  const beforeHidden = requests;
  await page.clock.runFor(60000);
  expect(requests).toBe(beforeHidden);
  used = 53;
  await page.evaluate(() => {
    Object.defineProperty(document, "visibilityState", {
      configurable: true,
      value: "visible",
    });
    document.dispatchEvent(new Event("visibilitychange"));
  });
  await expect(quota).toHaveAccessibleName(
    "53 used or queued of 200; 147 remaining",
  );
  hold = true;
  await page.evaluate(() => window.dispatchEvent(new Event("focus")));
  await expect.poll(() => !!held).toBe(true);
  const beforeHeld = requests;
  await page.evaluate(() => window.dispatchEvent(new Event("focus")));
  await page.clock.runFor(60000);
  expect(requests).toBe(beforeHeld);
  await held!.fulfill({ json: { used: 52, limit: 200 } });
  await expect(quota).toHaveAccessibleName(
    "52 used or queued of 200; 148 remaining",
  );
});

