    deletionCalls++;
    await new Promise((resolve) => setTimeout(resolve, 700));
    await route.fulfill({
      status: 200,
      contentType: "text/x-component",
      body: '0:{"a":"$@1","f":"","b":""}\n1:{"ok":false,"message":"Could not request deletion. Try again."}\n',
    });
  });
  await page
    .getByRole("button", { name: "Delete account", exact: true })
    .click();
  const dialog = page.getByRole("dialog");
  const input = dialog.getByLabel(`Type ${userId}@example.test to confirm`);
  await input.fill(`${userId}@example.test`);
  await dialog
    .getByRole("button", { name: "Request account deletion" })
    .click();
  await expect(
    dialog.getByRole("button", { name: "Requesting deletion…" }),
  ).toBeDisabled();
  await expect(input).toBeDisabled();
  await page.keyboard.press("Escape");
  await expect(dialog).toBeVisible();
  await expect(dialog.getByRole("alert")).toContainText(
    "Could not request deletion",
  );
  await expect(
    dialog.getByRole("button", { name: "Request account deletion" }),
  ).toBeEnabled();
  expect(deletionCalls).toBe(1);
  await dialog
    .getByRole("button", { name: "Request account deletion" })
    .click();
  await expect(
    dialog.getByRole("button", { name: "Cancel", exact: true }),
  ).toBeDisabled();
  await expect(dialog.getByRole("alert")).toContainText(
    "Could not request deletion",
  );
  await expect(
    dialog.getByRole("button", { name: "Request account deletion" }),
  ).toBeEnabled();
  expect(deletionCalls).toBe(2);
});

test("account deletion waits before logout and retries logout without repeating deletion", async ({
  page,
  userId,
}) => {
  await page.goto("/settings");
  let deletionCalls = 0;
  let signOutCalls = 0;
  let requestedAt = 0;
  await page.route("**/settings", async (route) => {
    if (
      !route.request().headers()["next-action"] ||
      !route.request().postData()?.includes(`${userId}@example.test`)
    )
      return route.continue();
    deletionCalls++;
    requestedAt = Date.now();
    await route.fulfill({
      status: 200,
      contentType: "text/x-component",
      body: '0:{"a":"$@1","f":"","b":""}\n1:{"ok":true,"message":"Deletion requested."}\n',
    });
  });
  await page.route("**/api/auth/signout", async (route) => {
    signOutCalls++;
    if (signOutCalls === 1) {
      expect(Date.now() - requestedAt).toBeGreaterThanOrEqual(2500);
      return route.fulfill({ status: 500, body: "Unable to sign out" });
    }
    return route.continue();
  });
  await page
    .getByRole("button", { name: "Delete account", exact: true })
    .click();
  await page
    .getByLabel(`Type ${userId}@example.test to confirm`)
    .fill(`${userId}@example.test`);
  await page.getByRole("button", { name: "Request account deletion" }).click();
  const dialog = page.getByRole("dialog", {
    name: "Account deletion requested",
    exact: true,
  });
  await expect(dialog.getByRole("status")).toHaveText(
    "Account deletion requested. You’ll be signed out shortly.",
  );
  await expect(page).toHaveURL(/settings$/);
  await expect.poll(() => signOutCalls, { timeout: 15000 }).toBe(1);
  await expect(
    dialog.getByRole("button", { name: "Retry sign-out" }),
  ).toBeVisible();
  await dialog.getByRole("button", { name: "Retry sign-out" }).click();
  await expect(page).toHaveURL(/\/\?deleted=1$/, { timeout: 15000 });
  expect(deletionCalls).toBe(1);
  expect(signOutCalls).toBe(2);
  await expect(
    page.getByRole("status").filter({ hasText: "Account deletion requested" }),
  ).toBeVisible();
});

