test("theme changes stay locked across workspace pages until sending ends", async ({
  page,
  userId,
}) => {
  await grantPremiumPlan(userId);
  await page.emulateMedia({ reducedMotion: "reduce" });
  const templateId = randomUUID(),
    contactId = randomUUID(),
    campaignId = randomUUID(),
    sendId = randomUUID();
  await pool.query(
    'INSERT INTO "Template" (id,"userId",name,subject,body) VALUES ($1,$2,$3,$4,$5)',
    [templateId, userId, "Theme lock fixture", "Hello", "Fixture"],
  );
  await pool.query(
    'INSERT INTO "Contact" (id,"userId",name,email) VALUES ($1,$2,$3,$4)',
    [contactId, userId, "Theme lock recipient", "[REDACTED_EMAIL]"],
  );
  await pool.query(
    'INSERT INTO "Campaign" (id,"userId","templateId",status) VALUES ($1,$2,$3,\'QUEUED\')',
    [campaignId, userId, templateId],
  );
  await page.goto("/compose");
  const trigger = page.getByRole("button", { name: "Choose appearance" });
  await expect(trigger).toBeEnabled();
  await trigger.click();
  await expect(page.getByRole("menu", { name: "Appearance" })).toBeVisible();
  // Database fixtures never dispatch an email or invoke Gmail.
  await pool.query(
    'INSERT INTO "Send" (id,"campaignId","contactId",status,"deliveryState") VALUES ($1,$2,$3,\'QUEUED\',\'READY\')',
    [sendId, campaignId, contactId],
  );
  await expect(trigger).toHaveAttribute("aria-disabled", "true", {
    timeout: 15000,
  });
  await expect(trigger).not.toHaveAttribute("title");
  await expect(page.getByRole("menu", { name: "Appearance" })).toHaveCount(0);
  const warning = page.getByRole("tooltip").filter({
    hasText:
      "Theme changes are unavailable while emails are being sent. Please wait until sending finishes.",
  });
  await page.mouse.move(0, 0);
  await expect(warning).toHaveCount(0);
  await trigger.hover();
  await expect(warning).toBeVisible();
  await page.mouse.move(0, 0);
  await expect(warning).toHaveCount(0);
  // Keyboard activation must not open either the warning or the theme menu.
  await trigger.focus();
  for (const key of ["Enter", "Space"]) {
    await page.keyboard.press(key);
    await expect(warning).toHaveCount(0);
  }
  await trigger.hover();
  await expect(warning).toBeVisible();
  await page.keyboard.press("Escape");
  await expect(warning).toHaveCount(0);
  // A click after Escape must not reopen the warning while still hovered.
  if (test.info().project.name === "mobile") await trigger.tap({ force: true });
  else await trigger.click({ force: true });
  await expect(warning).toHaveCount(0);
  await expect(page.getByRole("menu", { name: "Appearance" })).toHaveCount(0);
  await page.mouse.move(0, 0);
  await trigger.hover();
  await expect(warning).toBeVisible();
  await page.locator("h1").click();
  await expect(warning).toHaveCount(0);
  await page
    .getByRole("link", { name: "Settings", exact: true })
    .first()
    .click();
  await expect(trigger).toHaveAttribute("aria-disabled", "true");
  await page.reload();
  await expect(trigger).toHaveAttribute("aria-disabled", "true");
  await pool.query(
    'UPDATE "Send" SET "deliveryState"=\'ATTEMPTING\' WHERE id=$1',
    [sendId],
  );
  await page.evaluate(() => window.dispatchEvent(new Event("focus")));
  await expect(trigger).toHaveAttribute("aria-disabled", "true");
  await expect(page.locator("html")).toHaveAttribute("data-theme", "dark");
  await page.mouse.move(0, 0);
  await trigger.hover();
  await expect(warning).toBeVisible();
  await pool.query(
    "UPDATE \"Send\" SET status='CANCELLED', \"deliveryState\"='DONE' WHERE id=$1",
    [sendId],
  );
  await expect(trigger).toHaveAttribute("aria-disabled", "false", {
    timeout: 15000,
  });
  await expect(warning).toHaveCount(0);
  await trigger.click();
  await page
    .getByRole("menuitemradio", { name: "Chalk Light", exact: true })
    .click();
  await expect(page.locator("html")).toHaveAttribute("data-theme", "light");
  await expect(page.locator("html")).toHaveAttribute(
    "data-appearance",
    "vercel",
  );
  await pool.query(
    "UPDATE \"Send\" SET status='FAILED', \"deliveryState\"='UNCERTAIN' WHERE id=$1",
    [sendId],
  );
  await page.reload();
  await expect(trigger).toBeEnabled();
});

test("theme picker locks while submitting and unlocks after a rejected submission", async ({
  page,
  userId,
}) => {
  const { templateId } = await seedReadinessWorkspace(userId);
  await pool.query('DELETE FROM "Campaign" WHERE "userId"=$1', [userId]);
  await page.goto("/compose");
  await page
    .getByLabel("Choose a template", { exact: true })
    .selectOption(templateId);
  await page.getByRole("checkbox", { name: /^Maya/ }).check();
  const trigger = page.getByRole("button", { name: "Choose appearance" });
  await expect(trigger).toBeEnabled();
  let release!: () => void;
  const gate = new Promise<void>((resolve) => {
    release = resolve;
  });
  await page.route("**/compose", async (route) => {
    if (
      !route.request().headers()["next-action"] ||
      !route.request().postData()?.includes("idempotencyKey")
    )
      return route.continue();
    await gate;
    await route.fulfill({
      status: 200,
      contentType: "text/x-component",
      body: '0:{"a":"$@1","f":"","b":""}\n1:{"ok":false,"message":"Submission rejected for this test."}\n',
    });
  });
  try {
    await page.locator(".compose-send-button").click();
    await expect(page.locator(".compose-send-button")).toContainText("Queuing");
    await expect(trigger).toHaveAttribute("aria-disabled", "true");
    release();
    await expect(
      page.getByText("Submission rejected for this test.", { exact: true }),
    ).toBeVisible();
    await expect(trigger).toBeEnabled();
  } finally {
    release();
  }
});

