      await form.getByLabel("Email", { exact: true }).fill("[REDACTED_EMAIL]");
      await form.getByLabel("Name", { exact: true }).fill("Repeat Person");
      await form
        .getByLabel("Job role", { exact: true })
        .fill("Software Engineer Intern");
      await expect(form.locator("#contact-email-history-note")).toHaveText(
        "You’ve already emailed this address. You can still save this contact and send a follow-up.",
      );
      await form
        .getByRole("button", { name: "Save contact", exact: true })
        .click();
      await expect(
        page
          .getByTestId("success-toast")
          .getByText("Contact saved successfully.", { exact: true }),
      ).toBeVisible();
      await expect(
        page.getByRole("dialog", { name: "Upgrade to Premium", exact: true }),
      ).toHaveCount(0);
      const { rows: contacts } = await pool.query(
        'SELECT id,"archivedAt","shortlistRemovedAt","followUpRequestedAt" FROM "Contact" WHERE "userId"=$1',
        [userId],
      );
      expect(contacts).toHaveLength(1);
      expect(contacts[0]).toMatchObject({
        id: contactId,
        archivedAt: null,
        shortlistRemovedAt: null,
      });
      expect(contacts[0].followUpRequestedAt).not.toBeNull();
      expect(
        (
          await pool.query(
            'SELECT id FROM "Send" WHERE "campaignId" IN (SELECT id FROM "Campaign" WHERE "userId"=$1)',
            [userId],
          )
        ).rows,
      ).toHaveLength(0);
      await pool.query(
        'INSERT INTO "Contact" (id,"userId",name,email,"jobRole") VALUES ($1,$2,$3,$4,$5)',
        [
          randomUUID(),
          userId,
          "New Person",
          "[REDACTED_EMAIL]",
          "Software Engineer Intern",
        ],
      );
      await page.goto("/compose");
      const recipient = page.getByRole("checkbox", { name: /^Repeat Person/ });
      await expect(recipient).toBeEnabled();
      await expect(page.locator(".recipient-card-emailed")).toContainText(
        "You already emailed this address",
      );
      await page
        .getByRole("button", { name: "Select all", exact: true })
        .click();
      await expect(recipient).not.toBeChecked();
      await recipient.check();
      await expect(recipient).toBeChecked();
      await expect(
        page.getByRole("dialog", { name: "Upgrade to Premium", exact: true }),
      ).toHaveCount(0);
    } finally {
      await pool.query(
        'UPDATE "SystemControl" SET "paidGatingEnabled"=$1 WHERE key=\'global\'',
        [control.paidGatingEnabled],
      );
    }
  });
}

